"""Deutsch — Glaube und Gottesdienst (faith_001 … faith_070)."""

T = {
"faith_001": ("Wie viele Säulen hat der Islam?", ["5", "4", "6", "7"], "Der Hadith von Jibril und der von Ibn Umar überlieferte Hadith nennen die fünf Säulen des Islam."),
"faith_002": ("Wie heißt das Glaubensbekenntnis im Islam?", ["Die Shahada", "Das Salat", "Die Zakat", "Der Hadsch"], "Die Shahada, das Glaubenszeugnis, ist die erste Säule des Islam."),
"faith_003": ("Wie oft am Tag wird im Islam das Pflichtgebet verrichtet?", ["5", "3", "4", "7"], "Die fünf täglichen Pflichtgebete sind eine grundlegende Säule des Islam."),
"faith_004": ("Wie heißt die Pflichtabgabe im Islam?", ["Zakat", "Sadaqa", "Waqf", "Kaffara"], "Die Zakat ist die Pflichtabgabe, eine der fünf Säulen des Islam."),
"faith_005": ("Wie heißt der Pflichtfastenmonat im Islam?", ["Ramadan", "Shawwal", "Rajab", "Muharram"], "Der Koran gebietet das Fasten im Monat Ramadan."),
"faith_006": ("Wie heißt die Pilgerfahrt nach Mekka, die für jeden, der dazu in der Lage ist, einmal im Leben Pflicht ist?", ["Hadsch", "Umra", "I'tikaf", "Tawaf"], "Der Koran macht den Hadsch für jeden, der ihn unternehmen kann, mindestens einmal im Leben zur Pflicht."),
"faith_007": ("In welche Richtung wenden sich die Muslime beim Gebet?", ["Zur Ka'ba in Mekka", "Nach Jerusalem", "Nach Medina", "Nach Osten"], "Der Koran legte die Ka'ba als Gebetsrichtung (Qibla) fest."),
"faith_008": ("Wie viele Glaubensartikel (Säulen des Iman) werden laut einem bekannten Hadith üblicherweise gelehrt?", ["6", "4", "5", "7"], "Der Hadith von Jibril nennt sechs Glaubensartikel: Allah, die Engel, die Bücher, die Gesandten, den Jüngsten Tag und die göttliche Vorherbestimmung."),
"faith_009": ("Wie heißt die Reinigung mit Wasser, die ein Muslim vor jedem Gebet vornimmt?", ["Wudu (Gebetswaschung)", "Tayammum", "Ghusl", "Siwak"], "„Wenn ihr euch zum Gebet erhebt, wascht euer Gesicht und eure Hände…“: Das ist der Wudu."),
"faith_010": ("Was tun laut Koran die „edlen Schreiber“ (Kiraman Katibin)?", ["Sie zeichnen die Taten der Menschen auf", "Sie tragen den Thron", "Sie bewachen das Paradies", "Sie bringen den Regen"], "„Über euch sind Hüter, edle Schreiber“: Engel zeichnen jede Tat auf."),
"faith_011": ("Wie viele schöne Namen Allahs überliefert die authentische Tradition?", ["99", "50", "100", "114"], "Ein bei al-Buchari und Muslim überlieferter authentischer Hadith nennt neunundneunzig Namen: hundert weniger einen."),
"faith_012": ("Was bedeutet Allahs Name „Ar-Rahman“?", ["Der Allerbarmer", "Der Schöpfer", "Der König", "Der Allwissende"], "Ar-Rahman, der Allerbarmer: Seine Barmherzigkeit umfasst alle Dinge."),
"faith_013": ("Welchen Tages wird Allah in Al-Fatiha „Herrscher“ genannt?", ["Des Tages des Gerichts", "Des Freitags", "Des ersten Tages", "Des Tages von Arafa"], "„Herrscher am Tag des Gerichts“: der Tag, an dem jeder seinen Taten begegnet."),
"faith_014": ("An welchem Wochentag ruft der Koran die Gläubigen zum gemeinsamen Gebet?", ["Am Freitag", "Am Montag", "Am Samstag", "Am Sonntag"], "„Wenn am Freitag zum Gebet gerufen wird, eilt zum Gedenken Allahs.“"),
"faith_015": ("Wer garantiert laut Koran die Bewahrung des Korans vor jeder Veränderung?", ["Allah Selbst", "Nur die Engel", "Die Gelehrten", "Die Könige"], "„Wahrlich, Wir haben die Ermahnung herabgesandt, und Wir sind ihr Bewahrer.“"),
"faith_016": ("Was erklärt der Koran über den Eintritt in die Religion?", ["Es gibt keinen Zwang in der Religion", "Er geschieht durch einen Eid", "Er erfordert einen Zeugen", "Er geschieht im Erwachsenenalter"], "„Es gibt keinen Zwang in der Religion: Der rechte Weg ist klar vom Irrweg unterschieden.“"),
"faith_017": ("Wie lautet der Gruß der Muslime, ein Friedenswunsch?", ["As-salamu alaykum", "Marhaban", "Sabah al-khayr", "Ahlan wa sahlan"], "„As-salamu alaykum“: Friede sei mit euch; man antwortet „wa alaykum as-salam“."),
"faith_018": ("Wie heißt der Glaube an die Einheit Allahs, das Herz des Islam?", ["Tawhid", "Tafsir", "Tajwid", "Tarawih"], "Der Tawhid, das Bekenntnis, dass Allah Einer ist, ohne Teilhaber, ist das Fundament des ganzen Glaubens."),
"faith_019": ("Welches Buch offenbarte Allah dem Propheten Musa?", ["Die Tawrat (Tora)", "Das Injil (Evangelium)", "Den Zabur (Psalmen)", "Den Koran"], "„Wir sandten die Tawrat herab, in der Rechtleitung und Licht sind“ (5:44)."),
"faith_020": ("Welches Buch gab Allah dem Propheten Isa?", ["Das Injil (Evangelium)", "Die Tawrat", "Den Zabur", "Die Blätter Ibrahims"], "„Wir gaben ihm das Injil, in dem Rechtleitung und Licht sind“ (5:46)."),
"faith_021": ("Was soll man laut Koran tun, wenn man gegrüßt wird?", ["Mit einem besseren Gruß antworten oder ihn erwidern", "Schweigen", "Den Blick senken", "Nur Freunden antworten"], "„Wenn ihr mit einem Gruß gegrüßt werdet, so grüßt mit einem besseren oder erwidert ihn“ (4:86)."),
"faith_022": ("Die „Blätter“ (Suhuf) welcher zwei Propheten erwähnt die Sure Al-A'la?", ["Ibrahims und Musas", "Nuhs und Huds", "Dawuds und Sulaymans", "Zakariyyas und Yahyas"], "„Dies steht in den früheren Blättern, den Blättern Ibrahims und Musas“ (87:18-19)."),
"faith_023": ("Wie heißt der im Koran erwähnte Wächterengel der Hölle?", ["Malik", "Ridwan", "Mika'il", "Israfil"], "Die Leute der Hölle werden rufen: „O Malik, dein Herr möge uns ein Ende machen!“ (43:77)."),
"faith_024": ("Wie viele Engel werden laut Sure Al-Haqqa am Tag der Auferstehung den Thron Allahs tragen?", ["Acht", "Vier", "Zwölf", "Einer"], "„Und an jenem Tag werden acht über sich den Thron deines Herrn tragen“ (69:17)."),
"faith_025": ("Wer ist laut Koran damit beauftragt, die Seelen beim Tod zu nehmen?", ["Der Todesengel", "Jibril", "Der Prophet", "Die Dschinn"], "„Sprich: Der Todesengel, der über euch eingesetzt ist, wird eure Seelen nehmen“ (32:11)."),
"faith_026": ("Woraus wurden die Engel laut einem Hadith bei Sahih Muslim erschaffen?", ["Aus Licht", "Aus Feuer", "Aus Lehm", "Aus Wasser"], "„Die Engel wurden aus Licht erschaffen, die Dschinn aus rauchlosem Feuer und Adam aus dem, was euch beschrieben wurde.“"),
"faith_027": ("Woraus wurden die Dschinn laut Koran erschaffen?", ["Aus rauchlosem Feuer", "Aus Licht", "Aus Lehm", "Aus Wind"], "„Und Er erschuf die Dschinn aus einer rauchlosen Feuerflamme“ (55:15)."),
"faith_028": ("Wen nennt der Koran einen erklärten Feind des Menschen?", ["Satan (ash-Shaytan)", "Die Engel", "Die Tiere", "Die Nacht"], "„Wahrlich, Satan ist euch ein Feind; so nehmt ihn als Feind“ (35:6)."),
"faith_029": ("Wie viele Propheten werden „Ulu al-Azm“ (die Entschlossenen) genannt?", ["Fünf: Nuh, Ibrahim, Musa, Isa und Muhammad ﷺ", "Drei", "Zehn", "Fünfundzwanzig"], "„Sei geduldig, wie die entschlossenen Gesandten geduldig waren“ (46:35); die Sure Ash-Shura (42:13) nennt diese fünf gemeinsam."),
"faith_030": ("Worein wird laut Koran gestoßen, um die Auferstehung anzukündigen?", ["In die Posaune (as-Sur)", "In ein Widderhorn", "In eine Flöte", "In eine Glocke"], "„Es wird in die Posaune gestoßen, und wer in den Himmeln und auf der Erde ist, wird niederstürzen… dann wird erneut hineingestoßen“ (39:68)."),
"faith_031": ("Wie nennt der Koran das, was am Tag der Auferstehung die Taten wiegen wird?", ["Die Waagen (al-Mawazin)", "Das Register", "Die Brücke", "Die Posaune"], "„Wir werden am Tag der Auferstehung die gerechten Waagen aufstellen; keiner Seele wird in irgendetwas Unrecht getan“ (21:47)."),
"faith_032": ("Welchen Namen gibt der Koran der höchsten Stufe des Paradieses, die den Glaubenden und Gutes Tuenden verheißen ist?", ["Al-Firdaws", "Al-Kawthar", "As-Sirat", "Al-A'raf"], "„Diejenigen, die glauben und gute Werke tun, werden die Gärten des Firdaws zur Herberge haben“ (18:107)."),
"faith_033": ("Wie lautet der häufigste Name der Hölle im Koran?", ["Jahannam", "Firdaws", "Kawthar", "Tasnim"], "Der Koran nennt die Hölle dutzende Male „Jahannam“, zum Beispiel: „Ihr werdet zu Jahannam versammelt werden“ (3:12)."),
"faith_034": ("Welche Säule des Glaubens bekräftigt der Vers „Wir haben alles nach Maß erschaffen“?", ["Der Glaube an die göttliche Vorherbestimmung (al-Qadar)", "Der Glaube an die Engel", "Der Glaube an die Bücher", "Der Glaube an die Gesandten"], "„Wir haben alles nach einem Maß (Qadar) erschaffen“ (54:49): Nichts geschieht außerhalb von Allahs Wissen und Willen."),
"faith_035": ("Welche Sünde vergibt Allah laut Seiner Erklärung dem nicht, der stirbt, ohne sie bereut zu haben?", ["Shirk (Allah etwas beizugesellen)", "Die Lüge", "Den Geiz", "Den Zorn"], "„Allah vergibt nicht, dass Ihm etwas beigesellt wird, und Er vergibt, was geringer ist, wem Er will“ (4:48)."),
"faith_036": ("Wen liebt Allah laut Koran unter denen, die gesündigt haben?", ["Diejenigen, die bereuen", "Diejenigen, die ihre Sünden verbergen", "Diejenigen, die verzweifeln", "Diejenigen, die andere beschuldigen"], "„Wahrlich, Allah liebt die Reumütigen und liebt die sich Reinigenden“ (2:222)."),
"faith_037": ("Was bringt das Bitten um Vergebung (Istighfar) einem Volk laut Sure Nuh?", ["Reichlichen Regen und Segen", "Gar nichts", "Eine Dürre", "Einen langen Schlaf"], "„Bittet euren Herrn um Vergebung, denn Er ist allvergebend; Er wird den Himmel über euch in Strömen regnen lassen“ (71:10-11)."),
"faith_038": ("Was verspricht der Koran dem, der auf Allah vertraut (Tawakkul)?", ["Allah genügt ihm", "Er wird reich", "Er wird nie krank", "Er muss nicht mehr arbeiten"], "„Und wer auf Allah vertraut, dem genügt Er“ (65:3)."),
"faith_039": ("Was sagt Allah in der Sure Ghafir über das Bittgebet (Du'a)?", ["„Ruft Mich an, Ich werde euch erhören“", "„Ruft nur nachts“", "„Ruft die Engel an“", "„Das Du'a ist nur für Propheten“"], "„Euer Herr sagt: Ruft Mich an, Ich werde euch erhören“ (40:60)."),
"faith_040": ("Wodurch finden die Herzen laut Koran Ruhe?", ["Durch das Gedenken Allahs (Dhikr)", "Durch Geld", "Durch Schlaf", "Durch Reisen"], "„Finden die Herzen nicht Ruhe im Gedenken Allahs?“ (13:28)."),
"faith_041": ("Welches ist das erste Pflichtgebet des Tages?", ["Al-Fajr (Morgendämmerung)", "Adh-Dhuhr (Mittag)", "Al-Asr (Nachmittag)", "Al-Isha (Nacht)"], "Die fünf Gebete sind der Reihe nach: Fajr, Dhuhr, Asr, Maghrib und Isha."),
"faith_042": ("Wie viele Rak'a hat das Pflichtgebet Fajr?", ["Zwei", "Drei", "Vier", "Eine"], "Das Fajr hat zwei Rak'a; das Maghrib drei; Dhuhr, Asr und Isha je vier."),
"faith_043": ("Welches Pflichtgebet hat drei Rak'a?", ["Al-Maghrib", "Al-Fajr", "Adh-Dhuhr", "Al-Isha"], "Das Maghrib, gleich nach Sonnenuntergang, ist das einzige Pflichtgebet mit drei Rak'a."),
"faith_044": ("Wie heißt der Gebetsruf, der von der Moschee aus ertönt?", ["Der Adhan", "Die Khutba", "Der Tasbih", "Die Talbiya"], "Der Adhan wird vom Muezzin (Mu'adhdhin) vor jedem der fünf Gebete gerufen."),
"faith_045": ("Bis wohin sollen laut dem Vers über die Gebetswaschung die Arme gewaschen werden?", ["Bis zu den Ellbogen", "Bis zu den Handgelenken", "Bis zu den Schultern", "Nur die Hände"], "„Wascht euer Gesicht und eure Hände bis zu den Ellbogen, streicht über euren Kopf und wascht eure Füße bis zu den Knöcheln“ (5:6)."),
"faith_046": ("Was erlaubt der Koran, wenn vor dem Gebet kein Wasser zur Reinigung gefunden wird?", ["Den Tayammum mit reiner Erde", "Das Gebet ohne Reinigung", "Das Gebet auf den nächsten Tag zu verschieben", "Sich mit nassem Sand zu waschen"], "„Wenn ihr kein Wasser findet, so wendet euch reiner Erde zu und streicht damit über Gesicht und Hände“ (5:6)."),
"faith_047": ("Wie heißt die Predigt, die der Imam vor dem Freitagsgebet hält?", ["Die Khutba", "Der Adhan", "Die Iqama", "Der Takbir"], "Die Freitags-Khutba wird in zwei Teilen vom Minbar aus gehalten, vor dem Gebet."),
"faith_048": ("Welchen Anteil seiner ein ganzes Jahr gehaltenen Ersparnisse gibt ein Muslim als Zakat?", ["2,5 %", "10 %", "25 %", "1 %"], "Die Zakat auf gespartes Geld beträgt ein Viertel eines Zehntels, 2,5 %, sobald es ein Mondjahr lang über der Schwelle (Nisab) liegt."),
"faith_049": ("Welche besondere Abgabe ist am Ende des Ramadan, vor dem Eid-Gebet, fällig?", ["Die Zakat al-Fitr", "Die Zakat auf Gold", "Der Khums", "Die Kaffara"], "Der Prophet ﷺ machte die Zakat al-Fitr, ein Sa' Datteln oder Gerste, für jeden Muslim, jung oder alt, zur Pflicht."),
"faith_050": ("Von wann bis wann dauert laut Koran das tägliche Fasten im Ramadan?", ["Von der Morgendämmerung bis zur Nacht", "Vom Mittag bis zum Abend", "Vom Sonnenaufgang bis zum Mittag", "Den ganzen Tag und die ganze Nacht"], "„Esst und trinkt, bis sich der weiße Faden der Morgendämmerung vom schwarzen Faden unterscheidet, dann vollendet das Fasten bis zur Nacht“ (2:187)."),
"faith_051": ("Wie heißt die Mahlzeit, die vor der Morgendämmerung von dem eingenommen wird, der fasten wird?", ["Der Suhur", "Der Iftar", "Die Walima", "Die Aqiqa"], "Der Prophet ﷺ sagte: „Nehmt den Suhur ein, denn im Suhur liegt Segen.“"),
"faith_052": ("Wie heißt die Mahlzeit, mit der bei Sonnenuntergang das Fasten gebrochen wird?", ["Der Iftar", "Der Suhur", "Das Tarawih", "Das Tahajjud"], "Der Iftar bricht das Fasten, sobald die Sonne untergeht, zur Zeit des Maghrib-Gebets."),
"faith_053": ("Wie viele Feste (Eid) hat der Islam im Jahr?", ["Zwei: Eid al-Fitr und Eid al-Adha", "Nur eines", "Vier", "Zwölf"], "Das Eid al-Fitr schließt den Monat Ramadan ab; das Eid al-Adha fällt auf den 10. Dhul-Hijja, während der Pilgerfahrt."),
"faith_054": ("An welches Ereignis erinnert das Eid al-Adha?", ["An Ibrahims Opfer, ausgelöst durch einen Widder", "An die Geburt des Propheten ﷺ", "An die Schlacht von Badr", "An die Offenbarung des Korans"], "Bereit, seinen Sohn zu opfern, sah Ibrahim ihn ausgelöst: „Wir lösten ihn mit einem gewaltigen Opfer aus“ (37:107)."),
"faith_055": ("In welchem Monat des islamischen Kalenders findet die Pilgerfahrt (Hadsch) statt?", ["Dhul-Hijja", "Ramadan", "Muharram", "Rajab"], "Der Hadsch findet vom 8. bis 13. Dhul-Hijja statt, dem zwölften und letzten Monat des Mondjahres."),
"faith_056": ("An welchem Tag des Dhul-Hijja stehen die Pilger in der Ebene von Arafat?", ["Am 9.", "Am 1.", "Am 10.", "Am 27."], "Das Stehen in Arafat am 9. Dhul-Hijja ist die zentrale Säule des Hadsch; das Eid al-Adha folgt am nächsten Tag."),
"faith_057": ("Aus wie vielen Umrundungen der Ka'ba besteht ein Tawaf?", ["Sieben", "Drei", "Fünf", "Zehn"], "Der Tawaf besteht aus sieben Umrundungen der Ka'ba gegen den Uhrzeigersinn, beginnend am Schwarzen Stein."),
"faith_058": ("Aus wie vielen Läufen zwischen As-Safa und Al-Marwa besteht der Sa'y?", ["Sieben", "Zwei", "Vier", "Zwölf"], "Der Sa'y erinnert an Hajars Suche nach Wasser für Isma'il: sieben Läufe, von Safa nach Marwa und zurück, jede Richtung gezählt."),
"faith_059": ("Wie heißt der Weihezustand, in den der Pilger mit seinen zwei weißen Tüchern eintritt?", ["Der Ihram", "Der Tawaf", "Der Wuquf", "Die Talbiya"], "Im Ihram tragen Männer zwei ungenähte Tücher, und der Pilger verzichtet auf Parfüm, Jagd und Streit."),
"faith_060": ("Mit welchen Worten beginnt die Talbiya, die die Pilger auf dem Weg nach Mekka wiederholen?", ["„Labbayka Allahumma labbayk“ (Hier bin ich, o Allah, hier bin ich)", "„Allahu akbar“", "„Subhana Allah“", "„Al-hamdu li-Llah“"], "Die Talbiya des Propheten ﷺ lautete: „Labbayka Allahumma labbayk, labbayka la sharika laka labbayk…“"),
"faith_061": ("Was tun die Pilger in Mina, wenn sie Kieselsteine auf drei Säulen werfen?", ["Die Steinigung der Jamarat", "Den Tawaf", "Den Sa'y", "Das Stehen in Arafat"], "Das Ramy al-Jamarat erinnert daran, wie Ibrahim den Satan mit Steinen vertrieb; es findet in Mina an den Tagen des Eid statt."),
"faith_062": ("Wo befindet sich der Schwarze Stein (al-Hajar al-Aswad)?", ["In einer Ecke der Ka'ba", "Auf dem Berg Arafat", "In Medina", "Auf dem Gipfel des Berges Hira"], "In die östliche Ecke der Ka'ba eingelassen, markiert er den Ausgangspunkt jeder Umrundung des Tawaf."),
"faith_063": ("Wie heißt das große schwarze Tuch, das die Ka'ba bedeckt?", ["Die Kiswa", "Der Hijab", "Der Minbar", "Der Mihrab"], "Die Kiswa, mit Versen in Goldfaden bestickt, wird jedes Jahr während der Pilgerfahrt ersetzt."),
"faith_064": ("Wie heißt die „kleine“ Pilgerfahrt nach Mekka, die zu jeder Zeit des Jahres möglich ist?", ["Die Umra", "Der Hadsch", "Die Hidschra", "Die Ziyara"], "Die Umra besteht aus Ihram, Tawaf und Sa'y; anders als der Hadsch ist sie nicht an einen bestimmten Monat gebunden."),
"faith_065": ("Was bedeutet Allahs Name „Al-Khaliq“?", ["Der Schöpfer", "Der Vergebende", "Der Versorger", "Der König"], "„Er ist Allah, der Schöpfer (al-Khaliq), der Erschaffer, der Gestalter“ (59:24)."),
"faith_066": ("Was bedeutet Allahs Name „Al-Ghafur“?", ["Der Allvergebende", "Der Schöpfer", "Der Allmächtige", "Der Großzügige"], "„Verzweifelt nicht an Allahs Barmherzigkeit… Er ist der Vergebende (al-Ghafur), der Barmherzige“ (39:53)."),
"faith_067": ("Was bedeuten die beiden Namen Allahs „As-Sami'“ und „Al-Basir“?", ["Der Allhörende und der Allsehende", "Der König und der Richter", "Der Schöpfer und der Versorger", "Der Erste und der Letzte"], "Der Vers der Nachtreise endet: „Er ist der Hörende (as-Sami'), der Sehende (al-Basir)“ (17:1)."),
"faith_068": ("Was bedeutet „As-Samad“, ein Name Allahs in der Sure Al-Ikhlas?", ["Der, von dem alle abhängen und der von nichts abhängt", "Der Vergebende", "Der Hörende", "Der Erschaffende"], "„Allahu as-Samad“ (112:2): der absolute Herr, an den sich alle Geschöpfe mit ihren Bedürfnissen wenden."),
"faith_069": ("Welche zwei Namen Allahs eröffnen den Thronvers, gleich nach „Allah, es gibt keinen Gott außer Ihm“?", ["Al-Hayy und Al-Qayyum (der Lebendige, der Beständige)", "Ar-Rahman und Ar-Rahim", "Al-Malik und Al-Quddus", "Al-Aziz und Al-Hakim"], "„Allah! Es gibt keinen Gott außer Ihm, dem Lebendigen, dem Beständigen“ (2:255)."),
"faith_070": ("Was bedeutet Allahs Name „Ar-Razzaq“?", ["Der große Versorger", "Der Vergebende", "Der Gerechte", "Der Gütige"], "„Wahrlich, Allah ist der Versorger (ar-Razzaq), der Inhaber der Kraft, der Feste“ (51:58)."),
}
